WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY pressure DESC, id) AS latest_rank FROM device_readings QUALIFY latest_rank = 1) SELECT device_code, STDDEV_SAMP(temp_c) AS temp_c_stddev, BIT_AND(status_bits) AS status_bits_bit_and, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes FROM ranked GROUP BY device_code ORDER BY span_minutes
